<?php

declare(strict_types=1);

namespace HardnessWebhooks\Admin;

use HardnessWebhooks\Admin\Context\WebhookAdminContext;
use HardnessWebhooks\DestinationAuthentication\DestinationAuthenticationService;
use HardnessWebhooks\Delivery\DestinationValidator;
use HardnessWebhooks\Security\MasterKeyProvider;
use HardnessWebhooks\Security\SecretCipher;

/** Transaction boundary for independent administrative commands. */
final class WebhookAdminService
{
    private $repository; private $catalog; private $destinationValidator; private $destinationAuthentication;
    public function __construct(?WebhookAdminRepository $repository = null, ?WebhookAdminCatalogService $catalog = null, ?DestinationValidator $destinationValidator = null, ?DestinationAuthenticationService $destinationAuthentication = null) { $this->repository=$repository??new WebhookAdminRepository();$this->catalog=$catalog??new WebhookAdminCatalogService();$this->destinationValidator=$destinationValidator??new DestinationValidator();$this->destinationAuthentication=$destinationAuthentication; }
    /** @param array<string,mixed> $input */ public function create(\mysqli $connection,WebhookAdminContext $context,array $input): int { $data=$this->validate($connection,$context,$input); $auth=$data['destination_auth_type']==='N'?array('type'=>'N','ciphertext'=>null):$this->destinationAuthentication()->forCreate($data['destination_auth_type'],$data['destination_auth_token']); return $this->transaction($connection,function()use($context,$connection,$data,$auth):int{return $this->repository->create($context,$connection,$data['name'],$data['url'],$data['events'],$auth['type'],$auth['ciphertext']);}); }
    /** @param array<string,mixed> $input */ public function update(\mysqli $connection,WebhookAdminContext $context,int $id,array $input): void { $data=$this->validate($connection,$context,$input); $found=$this->transaction($connection,function()use($context,$connection,$id,$data):bool{$current=$this->repository->destinationAuthenticationForUpdate($context,$connection,$id);if($current===null)return false;$auth=$data['destination_auth_type']==='N'?array('type'=>'N','ciphertext'=>null):$this->destinationAuthentication()->forUpdate($data['destination_auth_type'],$data['destination_auth_token'],$current['type'],$current['ciphertext']);return $this->repository->update($context,$connection,$id,$data['name'],$data['url'],$data['events'],$auth['type'],$auth['ciphertext']);});if(!$found)throw new \OutOfBoundsException('Webhook não encontrado.'); }
    public function activate(\mysqli $connection,WebhookAdminContext $context,int $id): void { $this->transaction($connection,function()use($connection,$context,$id):void{$endpoint=$this->repository->find($context,$connection,$id);if($endpoint===null)throw new \OutOfBoundsException('Webhook não encontrado.');$current=$this->repository->destinationAuthenticationForUpdate($context,$connection,$id);if($current===null)throw new \OutOfBoundsException('Webhook não encontrado.');if($current['type']!=='N'||$current['ciphertext']!==null)$this->destinationAuthentication()->assertConfigured($current['type'],$current['ciphertext']);$this->destinationValidator->validate((string)$endpoint['url']);$allowed=array();foreach($this->catalog->available($connection,$context)as$event)$allowed[]=$event['type'];$this->repository->activate($context,$connection,$id,$allowed);}); }
    public function deactivate(\mysqli $connection,WebhookAdminContext $context,int $id): void { $found=$this->transaction($connection,function()use($connection,$context,$id):bool{return $this->repository->deactivate($context,$connection,$id);});if(!$found)throw new \OutOfBoundsException('Webhook não encontrado.'); }
    public function rescheduleDelivery(\mysqli $connection,WebhookAdminContext $context,int $endpointId,int $deliveryId): int { $newId=$this->transaction($connection,function()use($connection,$context,$endpointId,$deliveryId):int{return $this->repository->rescheduleDelivery($context,$connection,$endpointId,$deliveryId,self::uuidV4());});if($newId<1)throw new \OutOfBoundsException('Webhook não encontrado.');return $newId; }
    private function destinationAuthentication(): DestinationAuthenticationService { if(!$this->destinationAuthentication instanceof DestinationAuthenticationService)$this->destinationAuthentication=new DestinationAuthenticationService(new SecretCipher(MasterKeyProvider::fromEnvironment()));return $this->destinationAuthentication; }
    /** @param array<string,mixed> $input @return array{name:string,url:string,events:array<int,string>,destination_auth_type:mixed,destination_auth_token:mixed} */
    private function validate(\mysqli $connection,WebhookAdminContext $context,array $input):array { $name=isset($input['name'])&&is_string($input['name'])?trim($input['name']):'';$url=isset($input['url'])&&is_string($input['url'])?trim($input['url']):'';$events=isset($input['events'])&&is_array($input['events'])?$input['events']:null;$authType=$input['destination_auth_type']??'N';$authToken=$input['destination_auth_token']??'';if($name===''||$this->length($name)>150)throw new \InvalidArgumentException('Nome do webhook é inválido.');if($url===''||$this->length($url)>2048)throw new \InvalidArgumentException('URL do webhook é inválida.');if($events===null)throw new \InvalidArgumentException('Eventos do webhook são inválidos.');$clean=array();foreach($events as $event){if(!is_string($event)||$event===''||strlen($event)>100)throw new \InvalidArgumentException('Evento do webhook é inválido.');if(isset($clean[$event]))throw new \InvalidArgumentException('Evento duplicado.');$clean[$event]=$event;}$this->destinationValidator->validate($url);$selected=array_values($clean);$this->catalog->assertSelectable($connection,$context,$selected);return array('name'=>$name,'url'=>$url,'events'=>$selected,'destination_auth_type'=>$authType,'destination_auth_token'=>$authToken); }
    private function length(string $value):int{return function_exists('mb_strlen')?(int)mb_strlen($value,'UTF-8'):strlen($value);}
    private static function uuidV4():string{$bytes=random_bytes(16);$bytes[6]=chr((ord($bytes[6])&0x0f)|0x40);$bytes[8]=chr((ord($bytes[8])&0x3f)|0x80);$hex=bin2hex($bytes);return substr($hex,0,8).'-'.substr($hex,8,4).'-'.substr($hex,12,4).'-'.substr($hex,16,4).'-'.substr($hex,20);}
    private function transaction(\mysqli $connection,callable $operation){if(!$connection->begin_transaction())throw new \RuntimeException('Não foi possível iniciar operação administrativa.');try{$result=$operation();if(!$connection->commit())throw new \RuntimeException('Não foi possível concluir operação administrativa.');return $result;}catch(\Throwable $exception){$connection->rollback();throw $exception;}}
}
